<?php require __DIR__.'/../cms/config.php';require_login();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$p=$_POST['password']??'';$c=$_POST['confirm']??'';if(strlen($p)<10)$error='Use at least 10 characters.';elseif($p!==$c)$error='Passwords do not match.';else{$users=read_json('users');foreach($users as &$x)if((int)$x['id']===(int)$_SESSION['user']['id'])$x['password_hash']=password_hash($p,PASSWORD_DEFAULT);unset($x);write_json('users',$users);flash('Password changed.');redirect('index.php');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Change Password</title><link rel="stylesheet" href="../cms/cms.css"><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="auth"><div class="auth-card"><h1>Change password</h1><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>New password<input type="password" name="password" minlength="10" required></label><label>Confirm password<input type="password" name="confirm" minlength="10" required></label><button class="btn primary">Update password</button></form><a class="back" href="index.php">← Back to portal</a></div><script src="assets/dynamic-site.js"></script>
</body></html>